query:
SELECT id, question_text AS questionText, question_id AS questionId FROM ai_responses WHERE project_id = 1 LIMIT 10;
SELECT id, question_text AS questionText, source FROM questions WHERE project_id = 1 LIMIT 15;
SELECT COUNT(*) AS totalResponses, SUM(CASE WHEN question_text IS NULL OR question_text = '' THEN 1 ELSE 0 END) AS responsesMissingQuestionText, SUM(CASE WHEN question_id IS NULL THEN 1 ELSE 0 END) AS responsesMissingQuestionId FROM ai_responses WHERE project_id = 1;

